from typing import List

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            sl = []
            gaps = 0
            for j in range(i, n):
                v = nums[j]
                p = bisect.bisect_left(sl, v)
                if p < len(sl) and sl[p] == v:
                    total += gaps
                    continue
                has_prev = p > 0
                has_next = p < len(sl)
                if has_prev and has_next:
                    prev = sl[p-1]
                    nxt = sl[p]
                    gaps += (1 if v - prev > 1 else 0) + (1 if nxt - v > 1 else 0) - (1 if nxt - prev > 1 else 0)
                elif has_prev:
                    if v - sl[p-1] > 1:
                        gaps += 1
                elif has_next:
                    if sl[p] - v > 1:
                        gaps += 1
                sl.insert(p, v)
                total += gaps
        return total
